const ANSI_COLORS = {
  '0;30': 'black',
  '0;31': 'red',
  '0;32': 'green',
  '0;33': 'yellow',
  '0;34': 'blue',
  '0;35': 'magenta',
  '0;36': 'cyan',
  '0;37': 'white',
};

const ansiToHtml = (terminalOutputStr) => {
  return terminalOutputStr.replace(/\033\[([0-9;]+)m/g, (match, p1) => {
    const color = ANSI_COLORS[p1];
    return color ? `<span style="color:${color}">` : '</span>';
  }).replace(/\n/g, '<br />');
};

export default ansiToHtml;
